import json

def P(img, caption, legend=None):
    return {"img": img, "caption": caption, "legend": legend or {}}

def C(i, text, fig=""):
    return {"id": i, "text": text, "fig": fig}

def T(i, title, fields, how, back, abs_=False):
    return {"id": i, "title": title, "fields": fields, "how": how, "back": back, "abs": abs_}

